"""
    split at pos#k and swap halves
    a shorter ver. of r0
    """
def r3(a: Any, k: Any) -> object {
    n = len(a);
    k = k % n;
    return (a[(n - k):] + a[:(n - k)]);
}

"""
    Return the index <i> of the first occurance of <value>
    in the list <lst>, else return -1.

    >>> linear_search([1, 2, 3, 4], 3)
    2
    >>> linear_search([1, 2, 3, 4], 5)
    -1
    >>> linear_search([1, 2, 3, 4], 4)
    3
    >>> linear_search([1, 2, 3, 4], 1)
    0
    """
def linear_search(lst: list, value: object) -> int {
    i = 0;
    lst_length = len(lst);
    while ((i != lst_length) and (value != lst[i])) {
        i += 1;
    }
    if (i == lst_length) {
        return -1;
    } else {
        return i;
    }
}

"""Helper function for formating configuration output
    :param str name: name of the section being set, eg. paging or log
    :param str value: new value of the section
    :param str nearest: value of the nearest set section
    :param str path: path to the nearest set section
    :param str item_type: type of the setting, eg. blank, radio or edit
    :return: dictionary with configuration settings
    """
def format_configuration(
    name: Any, value: Any, nearest: Any, path: Any, item_type: Any
) -> object {
    name = name.replace('_', ' ');
    if (name == "paging") {
        item_type = "radio";
    } elif (name == "type") {
        item_type = "blank";
    }
    return {
        'name': name,
        'value': value,
        'nearest': nearest,
        'path': path,
        'type': item_type
    };
}
